import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { expect, it, vi } from 'vitest'
import { createDeliveryExport, EXPORT_RENDERER_VERSION } from '@/lib/delivery/export'
import { goldenVersions } from './golden-fixtures'
vi.mock('server-only', () => ({}))

// Captured ONCE through the actual untouched renderer at c6e37e6b, Node 24.22.2.
// These fixed files and hashes must never be regenerated by a changed renderer.
const hashes = {
  'unicode.json': '8411dc9c5e7352e46be91d1dfd799a4b980b6f6f0a112afc64e59e36e6dc58a8',
  'unicode.txt': 'cc0fe1cfd9d3b65afcd7c4fc8df60b14f2c45ccdaa3bc767c40bca1afa5cabaf',
  'precise.json': 'e9e5afad954ce182861b64e8b221298f93fc19c4c5f84c66a0f07cdd3e49d3c0',
  'precise.txt': '4704632df4a4b7dce26c6cbc8c2bd621aefc4215fc7ace60a720faae26be6e54',
  'spec.json': '0a0eb92535aaa210c55ea6130f081ff38944e4665e32ec43f98ef5aaf6f875ab',
  'spec.txt': '389d04f5dd90f63353e411656783ba9af7204b43dda8cea8784b9f8c8f9b6f26',
} as const
const sha256 = (bytes: string | Buffer) => createHash('sha256').update(bytes).digest('hex')

it.each(Object.entries(goldenVersions()))('preserves complete pre-change V1 JSON/text bytes and hashes: %s', (name, version) => {
  expect(EXPORT_RENDERER_VERSION).toBe('delivery-export.v1')
  for (const format of ['json', 'text'] as const) {
    const filename = `${name}.${format === 'json' ? 'json' : 'txt'}` as keyof typeof hashes
    const expected = readFileSync(resolve(process.cwd(), '__tests__/delivery/goldens', filename))
    const artifact = createDeliveryExport(version, format)
    expect(sha256(expected)).toBe(hashes[filename])
    expect(Buffer.from(artifact.body, 'utf8')).toEqual(expected)
    expect(artifact.exportHash).toBe(hashes[`${name}.json` as keyof typeof hashes])
    expect(artifact.filename).toBe(`delivery-${version.id}.${format === 'json' ? 'json' : 'txt'}`)
    expect(artifact.contentType).toBe(format === 'json' ? 'application/json; charset=utf-8' : 'text/plain; charset=utf-8')
  }
})
